@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + Birthday : date
}

abstract class BusinessOwner {
  + LinkedInAccount : string
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

class HungryCustomer {
  + DeliveryAddress : string
}

class Entertainer {
  + StageName : string
  + Bio : string
  + PricePer30Min : double
}

class Order {
  + OrderID : int
  + OrderDateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder {
  + EntertainmentType : string
  + Duration : int
}

class Availability {
  + Day : string
}

enum Day {
  Monday
  Tuesday
  Wednesday
  Thursday
  Friday
  Saturday
  Sunday
}

BusinessOwner --|> User
HungryCustomer --|> User
Entertainer --|> User

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
HungryCustomer "1" -- "*" Order : places
Order "1" -- "1..*" Pizza : contains
Order "1" -- "0..1" EntertainmentOrder : is_type

EntertainmentOrder "*" -- "1" Entertainer : fulfilled_by
Entertainer "1" -- "*" Availability : has
Availability "*" -- "1" PizzaRestaurant : for_restaurant

@enduml

